from nodes_train.common import PREV, ROOT, I, allr, ca, call, hn, lp, nc, rx, sc

NOTICE, SUMMARY, LINES, ACRO, JSON, REG, LIST, LEN = (
    "notice with exact constraints", "summary of a given text", "fixed line format", "acrostic", "JSON",
    "change of register", "list with line prefixes", "length limit")
LOWER = rx(r"\A[^А-ЯІЇЄҐA-Z]*\Z")
APOS = ("п'ятниц", "пʼятниц", "п’ятниц")


def upto(n):
    return rx(r"\A[\s\S]{1,%d}\Z" % n)


def words_upto(n):
    return rx(r"\A\s*(\S+\s+){0,%d}\S+\s*\Z" % (n - 1))


def jf(**fields):
    return {"type": "json_fields", "fields": fields}


def acro(word):
    return rx("(?s)^" + r".*\n".join(word))


